INSERT INTO "Teacher" ("id", "fullName", "gender", "birthPlace", "birthDate", "address", "phone", "photoUrl", "formalEducation", "nonFormalEducation", "certifications", "expertise", "philosophy", "bio", "joinDate", "isActive", "createdAt", "updatedAt") VALUES ('cmtufisci0001q12wh35dkb1p', 'Ustadzah Fatimah Az-Zahra, S.Pd.I', 'P', 'Bandung', 576806400000, 'Jl. Melati No. 12, Jakarta Timur', '081200000001', '/uploads/mtuwslje-73eacdea.jpg', '[{"level":"S2","institution":"UIN Syarif Hidayatullah Jakarta","year":"2015","major":"Pendidikan Agama Islam"},{"level":"S1","institution":"IAIN Syarif Hidayatullah","year":"2011","major":"Tadris PAI"}]', '[{"program":"Takhasush Qiroah","institution":"Ma''had Ali Darul Jinan","year":"2012"},{"program":"Pelatihan Guru TPQ (PGTPQ)","institution":"Kemenag Jakarta Timur","year":"2019"}]', '[{"name":"Sertifikat Kompetensi Guru TPQ","issuer":"Kemenag RI","year":"2020"},{"name":"Uji Kompetensi Tahsin & Tajwid","issuer":"Dewan Direktur LPQ","year":"2021"}]', 'Tajwid, Tahsin Usia Dini, Metode Qiroati', 'Anak adalah amanah. Mengajar Al-Qur''an bukan hanya memindahkan ilmu, tetapi menanamkan cinta kepada Kitabullah sejak dini.', 'Pengasuh utama kelas Iqra dengan pengalaman mengajar 12 tahun di lingkungan TPQ. Berfokus pada metode pembelajaran menyenangkan untuk santri usia 5-9 tahun.', 1341100800000, 1, 1788978353922, 1789007365153) ON CONFLICT DO NOTHING;
INSERT INTO "Teacher" ("id", "fullName", "gender", "birthPlace", "birthDate", "address", "phone", "photoUrl", "formalEducation", "nonFormalEducation", "certifications", "expertise", "philosophy", "bio", "joinDate", "isActive", "createdAt", "updatedAt") VALUES ('cmtufisck0004q12wvcdj1w7x', 'Ustadz Yusuf Rahman, Lc.', 'L', 'Surabaya', 654220800000, 'Jl. Kenanga No. 45, Jakarta Timur', '081200000002', '/uploads/mtuwslkm-0e10c186.jpg', '[{"level":"S1","institution":"Universitas Islam Madinah","year":"2014","major":"Syariah Islamiyah"}]', '[{"program":"Santri Mu''id Tahfidz 30 Juz","institution":"Ma''had Tahfidz Al-Hikmah","year":"2013"}]', '[{"name":"Sanad Al-Qur''an 30 Juz (Hafs)","issuer":"Majma'' Malik Fahd","year":"2015"},{"name":"Sertifikat Penguji Hafalan","issuer":"BMTQ PNF Jatim","year":"2022"}]', 'Tahfidz 30 Juz, Sanad Qiroah, Penguji Hafalan', 'Setiap ayat yang terhafal adalah cahaya di akhirat. Konsistensi dan istiqamah adalah kunci, bukan kecepatan.', 'Hafizh 30 juz bersanad, pendamping program Tahfidz intensif. Terbiasa memantau setoran hafalan harian santri dengan sistem target harian.', 1423958400000, 1, 1788978353925, 1789007365195) ON CONFLICT DO NOTHING;
INSERT INTO "Teacher" ("id", "fullName", "gender", "birthPlace", "birthDate", "address", "phone", "photoUrl", "formalEducation", "nonFormalEducation", "certifications", "expertise", "philosophy", "bio", "joinDate", "isActive", "createdAt", "updatedAt") VALUES ('cmtufiscm0007q12whe9aou6a', 'Ustadzah Khadijah Rahmawati', 'P', 'Bekasi', 790387200000, 'Perum Griya Asri Blok C-8, Bekasi', '081200000003', '/uploads/mtuwsllm-06d2b9f1.jpg', '[{"level":"S1","institution":"Universitas Pendidikan Indonesia","year":"2017","major":"Pendidikan Anak Usia Dini"}]', '[{"program":"Tahsin & Tajwid","institution":"TPQ Al-Ikhlas","year":"2018"},{"program":"Montessori Islamic Approach","institution":"IGTI Jakarta","year":"2021"}]', '[{"name":"Sertifikat Kompetensi Guru TPQ","issuer":"Kemenag RI","year":"2022"}]', 'Metode Bermain Sambil Belajar, Akhlak & Adab, Bimbingan Usia Dini', 'Belajar Islam untuk anak harus terasa seperti bermain di rumahnya sendiri — penuh kasih sayang dan tanpa paksaan.', 'Spesialis pembelajaran santri usia dini (4-7 tahun) dengan pendekatan fun learning berbasis nilai-nilai Islam.', 1528588800000, 1, 1788978353927, 1789007365251) ON CONFLICT DO NOTHING;
INSERT INTO "Teacher" ("id", "fullName", "gender", "birthPlace", "birthDate", "address", "phone", "photoUrl", "formalEducation", "nonFormalEducation", "certifications", "expertise", "philosophy", "bio", "joinDate", "isActive", "createdAt", "updatedAt") VALUES ('cmtufiscp000aq12wvb5ijazm', 'Ustadz Ibrahim Musa, S.Pd.', 'L', 'Depok', 502156800000, 'Jl. Cempaka Putih No. 7, Jakarta Timur', '081200000004', '/uploads/mtuwslex-da13167e.jpg', '[{"level":"S1","institution":"Universitas Islam Negeri Jakarta","year":"2008","major":"Pendidikan Bahasa Arab"}]', '[{"program":"Kaderisasi Ulama Muda","institution":"DDI Jawa Barat","year":"2009"}]', '[{"name":"Sertifikat Instruktur Fiqih Ibadah","issuer":"BIMAS Islam Kemenag","year":"2019"}]', 'Fiqih Ibadah, Praktik Sholat, Kaligrafi', 'Ibadah yang diajarkan dengan praktik langsung akan membekas lebih lama daripada seribu teori.', 'Guru praktik ibadah dan pelatih lomba kaligrafi. Membimbing santri kelas Al-Qur''an dan materi latihan ibadah harian.', 1280620800000, 1, 1788978353929, 1789007365053) ON CONFLICT DO NOTHING;
