INSERT INTO "Post" ("id", "title", "slug", "content", "category", "coverImage", "published", "authorId", "createdAt", "updatedAt") VALUES ('cmtufise2003qq12wv0qf338f', 'Khataman Al-Qur''an Santri Tahfidz Batch 2025', 'khataman-santri-tahfidz-2025', 'Alhamdulillah, pada hari Ahad lalu TPQ Darul Jinan menyelenggarakan hawaman (khataman) Al-Qur''an bagi 7 santri Tahfidz yang telah menyelesaikan hafalan 30 juz. Acara berlangsung khidmat di aula TPQ, dihadiri seluruh wali santri, guru, dan tokoh masyarakat sekitar.
INSERT INTO "Post" ("id", "title", "slug", "content", "category", "coverImage", "published", "authorId", "createdAt", "updatedAt") VALUES ('cmtufise3003sq12wma6q73f7', 'Perlombaan Tilawah & Hafalan Antar Kelas', 'perlombaan-tilawah-hafalan', 'Dalam rangka menyambut bulan penuh keberkahan, TPQ Darul Jinan menggelar lomba tilawah dan hafalan juz 30 antar kelas. Lomba diikuti 40+ santri dari 4 kelas dengan kategori: tilawah anak (Iqra), tahfidz juz 30, dan kaligrafi.
INSERT INTO "Post" ("id", "title", "slug", "content", "category", "coverImage", "published", "authorId", "createdAt", "updatedAt") VALUES ('cmtufise4003uq12wd8em6wpr', '5 Tips Membimbing Anak Setoran Hafalan di Rumah', 'tips-bimbingan-hafalan-anak', '1. Tetapkan waktu istiqamah — pilih jam yang sama setiap hari, misalnya setelah subuh atau setelah maghrib.
INSERT INTO "Post" ("id", "title", "slug", "content", "category", "coverImage", "published", "authorId", "createdAt", "updatedAt") VALUES ('cmtufise4003wq12wafbv13vo', 'Pendaftaran Santri Baru (PPDB) Gelombang II Dibuka', 'ppdb-gelombang-2-dibuka', 'TPQ Darul Jinan membuka Penerimaan Peserta Didik Baru (PPDB) Gelombang II untuk kelas Iqra, Al-Qur''an, dan Tahfidz.
INSERT INTO "Announcement" ("id", "title", "content", "priority", "createdAt") VALUES ('cmtufise5003xq12w9ikoqh03', 'Libur Idul Adha', 'Pembelajaran TPQ diliburkan pada 10-12 Dzulhijjah. Kegiatan rutin dilanjutkan kembali sesuai jadwal.', 'PENTING', 1788978353982) ON CONFLICT DO NOTHING;
INSERT INTO "Announcement" ("id", "title", "content", "priority", "createdAt") VALUES ('cmtufise6003yq12wswuukm7h', 'Rapat Wali Santri', 'Rapat wali santri semester ini dilaksanakan hari Sabtu pukul 09.00 di aula TPQ. Mohon kehadirannya.', 'NORMAL', 1788978353982) ON CONFLICT DO NOTHING;
INSERT INTO "Announcement" ("id", "title", "content", "priority", "createdAt") VALUES ('cmtufise6003zq12wiqmc7b1i', 'Pembayaran Iuran Bulan Ini', 'Batas pembayaran iuran tanggal 25. Bayar mudah via QRIS di Portal Wali.', 'NORMAL', 1788978353983) ON CONFLICT DO NOTHING;
INSERT INTO "Curriculum" ("id", "classId", "level", "subject", "description", "target", "order") VALUES ('cmtufisd70018q12wmvyss9g1', 'cmtufiscr000eq12w6ru18mza', 'Iqra 1-2', 'TAJWID', 'Pengenalan huruf hijaiyah, harakat fathah-kasrah-dhommah, dan tanwin.', 'Santri mampu membaca Iqra jilid 1-2 dengan lancar.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "Curriculum" ("id", "classId", "level", "subject", "description", "target", "order") VALUES ('cmtufisd8001aq12w42kxqlxs', 'cmtufiscs000gq12woyrtg49i', 'Iqra 3-6', 'TAJWID', 'Mad, sukun, tasydid, hukum nun sukun & mim sukun dasar.', 'Santri tamat Iqra dan siap beralih ke Al-Qur''an.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "Curriculum" ("id", "classId", "level", "subject", "description", "target", "order") VALUES ('cmtufisd9001cq12wd3qbs4nm', 'cmtufiscu000kq12wa5d9jpcw', 'Al-Qur''an A', 'TAJWID', 'Tilawah Al-Qur''an dengan tartil, hukum tajwid lengkap, tahsin harfiah.', 'Santri membaca Al-Qur''an sesuai kaidah tajwid.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "Curriculum" ("id", "classId", "level", "subject", "description", "target", "order") VALUES ('cmtufisd9001eq12wpsd1cxnm', 'cmtufiscu000iq12wxvkqeqry', 'Tahfidz A', 'HAFALAN', 'Setoran hafalan juz 30 (Juz ''Amma) dengan target 3-5 ayat/minggu, murajaah pekanan.', 'Khatam Juz 30 dengan sanad terverifikasi.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "Curriculum" ("id", "classId", "level", "subject", "description", "target", "order") VALUES ('cmtufisd9001gq12wpt3269v7', NULL, 'Semua Kelas', 'IBADAH', 'Praktik wudhu, sholat 5 waktu, doa harian, dan dzikir pagi-petang.', 'Santri mandiri beribadah dengan tertib.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "Curriculum" ("id", "classId", "level", "subject", "description", "target", "order") VALUES ('cmtufisda001iq12w23yn2wws', NULL, 'Semua Kelas', 'AKHLAK', 'Adab kepada orang tua, guru, dan teman; sopan santun sehari-hari.', 'Pembentukan karakter akhlakul karimah.', 6) ON CONFLICT DO NOTHING;
INSERT INTO "SiteSetting" ("key", "value", "updatedAt") VALUES ('hero', '{"bismillah":"بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ","badge":"Taman Pendidikan Al-Qur''an","title":"TPQ Darul Jinan","tagline":"Mendidik generasi Qur''ani yang hafal, paham, dan berakhlak mulia — membimbing anak menumbuhkan cinta pada Al-Qur''an sejak usia dini dengan bimbingan ustadz dan ustadzah tersertifikasi.","showStats":true,"logoUrl":"","backgroundUrl":"/images/hero-mosque.jpg"}', 1789007115790) ON CONFLICT DO NOTHING;
INSERT INTO "SiteSetting" ("key", "value", "updatedAt") VALUES ('about', '{"badge":"Tentang Kami","heading":"Membina Generasi Qur''ani yang Berakhlak Mulia","tagline":"TPQ Darul Jinan adalah lembaga pendidikan Al-Qur''an untuk anak dan remaja di Cibubur, Jakarta Timur — berkhidmat menanamkan cinta Al-Qur''an sejak dini.","vision":"Menjadi TPQ yang unggul dalam melahirkan generasi penghafal dan pencinta Al-Qur''an yang berakhlak mulia, beradab, dan bermanfaat bagi umat.","missions":["Menyelenggarakan pembelajaran Al-Qur''an yang aktif, menyenangkan, dan menyenangkan hati anak.","Membina santri agar mampu membaca Al-Qur''an dengan tajwid yang benar dan lancar.","Menumbuhkan hafalan juz ''amma dan surat-surat pilihan sebagai bekal ibadah harian.","Menanamkan akhlak mulai dari adab kepada orang tua, guru, dan teman sebaya.","Membangun kemitraan erat antara TPQ dan wali santri melalui komunikasi yang transparan."],"imageUrl":"/images/tpq-learning.jpg"}', 1789007064151) ON CONFLICT DO NOTHING;
INSERT INTO "SiteSetting" ("key", "value", "updatedAt") VALUES ('contact', '{"address":"Jl. Merpati Raya No. 25, Cibubur, Jakarta Timur","phone":"0812-3456-7890","whatsapp":"6281234567890","email":"info@daruljinan.sch.id","hoursNote":"Senin – Sabtu 15.00 – 18.00 WIB · Ahad libur"}', 1789007064153) ON CONFLICT DO NOTHING;
INSERT INTO "SiteSetting" ("key", "value", "updatedAt") VALUES ('faqs', '[{"question":"Berapa iuran (SPP) per bulan, dan apakah ada uang pangkal?","answer":"Iuran bulanan (SPP) Rp 75.000 – Rp 100.000 tergantung program yang diikuti (Iqra, Al-Qur''an, atau Tahfidz). Tidak ada uang pangkal — pendaftaran PPDB gratis; santri hanya menyiapkan seragam serta kitab/Al-Qur''an masing-masing."},{"question":"Kapan jadwal belajar TPQ?","answer":"Kegiatan belajar berlangsung Senin sampai Sabtu pukul 15.00 – 18.00 WIB sesuai jadwal kelas masing-masing (Ahad libur). Rincian jadwal per kelas dapat dilihat pada bagian Kurikulum di halaman ini."},{"question":"Usia berapa anak bisa mendaftar?","answer":"Pendaftaran dibuka untuk anak usia 4 – 15 tahun. Anak usia 4 – 6 tahun akan ditempatkan pada kelas Iqra pemula dengan metode bermain sambil belajar agar tetap nyaman."},{"question":"Program apa saja yang tersedia?","answer":"Tersedia tiga program utama: Iqra (tahap awal membaca), Al-Qur''an (tahsin/perbaikan bacaan), dan Tahfidz (hafalan Al-Qur''an dengan target juz). Penempatan program mengikuti hasil tes penempatan saat verifikasi."},{"question":"Bagaimana cara mendaftar?","answer":"Isi formulir PPDB online pada bagian PPDB di halaman ini, lalu catat nomor registrasi yang muncul. Selanjutnya bawa dokumen (akta kelahiran, kartu keluarga, dan pas foto) saat verifikasi di sekretariat TPQ."},{"question":"Bagaimana cara membayar tagihan/SPP?","answer":"Pembayaran dilakukan melalui Portal Wali: pilih tagihan lalu bayar via QRIS, GoPay, atau Virtual Account. Setelah transaksi berhasil, konfirmasi pembayaran dikirim otomatis melalui WhatsApp."},{"question":"Apakah orang tua mendapat laporan perkembangan anak?","answer":"Ya. Melalui Portal Wali, orang tua dapat memantau kehadiran (absensi), progres hafalan beserta nilai dan catatan ustadz/ustadzah, serta tagihan bulanan. Rapor perkembangan juga dibagikan setiap akhir semester."}]', 1789007064156) ON CONFLICT DO NOTHING;
INSERT INTO "SiteSetting" ("key", "value", "updatedAt") VALUES ('testimonials', '[{"quote":"Anak saya jadi mandiri mengaji setelah ikut program Tahfidz. Ustadzahnya sabar banget menghadapi anak yang mudah bosan, sekarang hafalannya sudah lebih dari tiga juz. Alhamdulillah.","name":"Bpk. Hendra Gunawan","role":"Wali santri — Program Tahfidz"},{"quote":"Awalnya anak saya sering enggan ke TPQ, sekarang justru dia yang mengingatkan jadwal ngaji. Metode Iqra di sini menyenangkan, anak-anak betah dan semangat.","name":"Ibu Ratna Sari","role":"Wali santri — Kelas Iqra 3"},{"quote":"Laporan perkembangan di Portal Wali sangat membantu. Kehadiran, hafalan, sampai tagihan bulanan bisa saya pantau dari HP, dan komunikasi dengan ustadz lewat WhatsApp selalu cepat dibalas.","name":"Bpk. Ahmad Fauzi","role":"Wali santri — Kelas Al-Qur''an B"},{"quote":"Fasilitas nyaman dan pengajarnya komunikatif. Anak saya bukan cuma lancar membaca Al-Qur’an, akhlaknya juga makin sopan dan terbiasa shalat berjamaah di rumah.","name":"Ibu Dewi Lestari","role":"Wali santri — Kelas Tahsin"}]', 1789007064158) ON CONFLICT DO NOTHING;
